import io
import os
from typing import Any, Dict, List, Optional, Union

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential


def _read_document_bytes(document: Union[str, bytes, bytearray, io.BufferedIOBase]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if hasattr(document, "read"):
        data = document.read()
        return data if isinstance(data, bytes) else data.encode("utf-8")
    if isinstance(document, str):
        with open(document, "rb") as f:
            return f.read()
    raise TypeError("document must be a file path, bytes, or file-like object")


def _page_text(page: Any) -> str:
    parts = []
    for line in getattr(page, "lines", []) or []:
        txt = getattr(line, "content", None)
        if txt:
            parts.append(txt)
    return "\n".join(parts)


def _field_value_to_python(value: Any) -> Any:
    if value is None:
        return None

    vtype = getattr(value, "type", None)
    if vtype == "string":
        return getattr(value, "value_string", None)
    if vtype == "date":
        return getattr(value, "value_date", None)
    if vtype == "time":
        return getattr(value, "value_time", None)
    if vtype == "phoneNumber":
        return getattr(value, "value_phone_number", None)
    if vtype == "number":
        return getattr(value, "value_number", None)
    if vtype == "integer":
        return getattr(value, "value_integer", None)
    if vtype == "selectionMark":
        return getattr(value, "value_selection_mark", None)
    if vtype == "countryRegion":
        return getattr(value, "value_country_region", None)
    if vtype == "currency":
        cur = getattr(value, "value_currency", None)
        if cur is not None:
            return {
                "amount": getattr(cur, "amount", None),
                "currencyCode": getattr(cur, "currency_code", None),
            }
    if vtype == "array":
        items = getattr(value, "value_array", None) or []
        return [_field_value_to_python(item) for item in items]
    if vtype == "object":
        obj = getattr(value, "value_object", None) or {}
        return {k: _field_value_to_python(v) for k, v in obj.items()}
    if vtype == "dictionary":
        dct = getattr(value, "value_dictionary", None) or {}
        return {k: _field_value_to_python(v) for k, v in dct.items()}

    for attr in (
        "value_string",
        "value_date",
        "value_time",
        "value_phone_number",
        "value_number",
        "value_integer",
        "value_selection_mark",
        "value_country_region",
    ):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if v is not None:
                return v

    return getattr(value, "content", None)


def _extract_key_value_pairs_from_result(result: Any) -> Dict[str, Any]:
    extracted: Dict[str, Any] = {}

    for kv_pair in getattr(result, "key_value_pairs", []) or []:
        key_obj = getattr(kv_pair, "key", None)
        value_obj = getattr(kv_pair, "value", None)

        key = getattr(key_obj, "content", None) or getattr(kv_pair, "key_content", None)
        value = getattr(value_obj, "content", None) if value_obj is not None else None

        if key:
            extracted[key.strip()] = value.strip() if isinstance(value, str) else value

    for field_name, field in (getattr(result, "documents", None) or [{}])[0].items() if isinstance(getattr(result, "documents", None), list) and getattr(result, "documents", None) else []:
        if field_name and field is not None:
            extracted[field_name] = _field_value_to_python(field)

    return extracted


def extract_key_value_pairs(
    document: Union[str, bytes, bytearray, io.BufferedIOBase],
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
    model_id: str = "prebuilt-document",
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValueError("Azure Document Intelligence endpoint is required")
    if not key:
        raise ValueError("Azure Document Intelligence key is required")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    document_bytes = _read_document_bytes(document)

    poller = client.begin_analyze_document(
        model_id=model_id,
        analyze_request=AnalyzeDocumentRequest(bytes_source=document_bytes),
    )
    result = poller.result()

    extracted = _extract_key_value_pairs_from_result(result)

    if not extracted and hasattr(result, "content") and getattr(result, "content", None):
        extracted["__text__"] = result.content

    return extracted
